import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "kanban-board.html"
SCRIPT_ID = "app"
FEATURES = ["columns", "cards", "move", "wiplimit", "labels", "search", "due", "sortcolumn",
            "archive", "history", "swimlanes", "assignees", "exporter", "importer", "metrics", "persist"]

DRIVER = r"""
const fs = require('fs');
const vm = require('vm');
const noop = () => {};
function el() {
  return {
    innerHTML: '', textContent: '', value: '', checked: false, style: {}, dataset: {},
    children: [], childNodes: [], parentNode: null,
    classList: { add: noop, remove: noop, toggle: noop, contains: () => false },
    addEventListener: noop, removeEventListener: noop, dispatchEvent: noop,
    appendChild: (x) => x, append: noop, prepend: noop, removeChild: noop,
    replaceChildren: noop, insertBefore: noop, remove: noop, setAttribute: noop,
    removeAttribute: noop, getAttribute: () => null, hasAttribute: () => false,
    focus: noop, blur: noop, click: noop, closest: () => null, matches: () => false,
    querySelector: () => el(), querySelectorAll: () => [], getElementsByTagName: () => [],
    getBoundingClientRect: () => ({ x: 0, y: 0, width: 0, height: 0, top: 0, left: 0, right: 0, bottom: 0 }),
  };
}
const bag = new Map();
const storage = {
  getItem: (k) => (bag.has(String(k)) ? bag.get(String(k)) : null),
  setItem: (k, v) => { bag.set(String(k), String(v)); },
  removeItem: (k) => { bag.delete(String(k)); },
  clear: () => bag.clear(),
  key: (i) => Array.from(bag.keys())[i] ?? null,
  get length() { return bag.size; },
};
Object.defineProperty(globalThis, 'localStorage', { value: storage, configurable: true, writable: true });
globalThis.document = Object.assign(el(), {
  getElementById: () => el(), createElement: () => el(), createElementNS: () => el(),
  createTextNode: (t) => ({ textContent: String(t) }), createDocumentFragment: () => el(),
  body: el(), head: el(), documentElement: el(), readyState: 'loading',
});
globalThis.window = globalThis;
globalThis.location = { hash: '', href: '', search: '' };
globalThis.history = { pushState: noop, replaceState: noop };
globalThis.requestAnimationFrame = () => 0;
globalThis.alert = noop; globalThis.confirm = () => true; globalThis.prompt = () => null;

const out = { app: false, features: {} };
try {
  vm.runInThisContext(fs.readFileSync('app.js', 'utf8'), { filename: 'app.js' });
} catch (e) {
  out.load_error = String((e && e.stack) || e).slice(0, 800);
}
const App = globalThis.App;
out.app = !!(App && App.features && typeof App.features === 'object');

const COLS = [
  { id: 'todo', name: 'To do', wip: null },
  { id: 'doing', name: 'Doing', wip: 2 },
  { id: 'done', name: 'Done', wip: null },
];
const CARDS = [
  { id: 'c1', title: 'Write spec', description: 'Draft the kanban spec', tags: ['docs', 'Urgent'], due: '2026-03-10', assignee: 'ana', column: 'todo', created: '2026-03-01', done: null, archived: false },
  { id: 'c2', title: 'Fix login bug', description: 'Session cookie not cleared', tags: ['bug'], due: '2026-03-04', assignee: 'ben', column: 'doing', created: '2026-03-02', done: null, archived: false },
  { id: 'c3', title: 'Design logo', description: '', tags: ['design'], due: null, assignee: null, column: 'todo', created: '2026-02-20', done: null, archived: false },
  { id: 'c4', title: 'Ship v1', description: 'Release notes and tag', tags: ['docs', 'release'], due: '2026-03-03', assignee: 'ana', column: 'doing', created: '2026-02-25', done: null, archived: false },
  { id: 'c5', title: 'Set up CI', description: 'urgent: pipeline is red', tags: ['bug', 'infra'], due: '2026-02-28', assignee: 'ben', column: 'done', created: '2026-02-21', done: '2026-02-27', archived: false },
  { id: 'c6', title: 'Old task', description: 'archived long ago', tags: [], due: null, assignee: 'ana', column: 'done', created: '2026-01-10', done: '2026-01-12', archived: true },
];
const STATE = { columns: COLS, cards: CARDS, ui: {} };
const ids = (list) => (list || []).map((c) => c.id);
const frozen = JSON.stringify([COLS, CARDS]);

function feature(name, fn) {
  const r = { present: false, has_model: false, has_render: false };
  try {
    const f = App && App.features && App.features[name];
    r.present = !!f;
    if (f) {
      r.has_model = !!f.model && typeof f.model === 'object';
      r.has_render = typeof f.render === 'function';
      Object.assign(r, fn(f.model));
      r.mutated_input = JSON.stringify([COLS, CARDS]) !== frozen;
    }
  } catch (e) {
    r.error = String((e && e.stack) || e).slice(0, 600);
  }
  out.features[name] = r;
}

feature('columns', (m) => {
  const added = m.add(COLS, 'Review');
  const renamed = m.rename(COLS, 'doing', 'In progress');
  return {
    original: COLS.length, after_add: added.length,
    new_col: { name: added[added.length - 1].name, has_id: !!added[added.length - 1].id, wip: added[added.length - 1].wip },
    renamed: renamed.map((c) => c.name), removed: m.remove(COLS, 'doing').map((c) => c.id),
    ok_errors: m.validate('Review', COLS), blank_errors: m.validate('   ', COLS), dup_errors: m.validate('to DO', COLS),
  };
});

feature('cards', (m) => {
  const one = m.add(CARDS, { title: 'New card', description: '', tags: ['x'], due: null, assignee: null, column: 'todo', created: '2026-03-05' });
  const last = one[one.length - 1];
  return {
    original: CARDS.length, after_add: one.length,
    added: { title: last.title, column: last.column, has_id: !!last.id && !ids(CARDS).includes(last.id), archived: last.archived, done: last.done },
    updated: m.update(CARDS, 'c3', { title: 'Design new logo', due: '2026-04-01' }).find((c) => c.id === 'c3'),
    removed: ids(m.remove(CARDS, 'c2')),
    ok_errors: m.validate({ title: 'ok', description: '', tags: ['a'], due: '2026-03-01', column: 'todo' }),
    bad_errors: m.validate({ title: '  ', description: '', tags: ['a', ''], due: '3/1/2026', column: 'todo' }),
  };
});

feature('move', (m) => ({
  todo_before: ids(m.inColumn(CARDS, 'todo')), done_before: ids(m.inColumn(CARDS, 'done')),
  to_done_first: ids(m.inColumn(m.move(CARDS, 'c1', 'done', 0), 'done')),
  to_doing_last: ids(m.inColumn(m.move(CARDS, 'c3', 'doing', 99), 'doing')),
  reorder: ids(m.inColumn(m.move(CARDS, 'c4', 'doing', 0), 'doing')),
  original_todo: ids(m.inColumn(CARDS, 'todo')), untouched_after_move: m.move(CARDS, 'c1', 'done', 0).length,
}));

feature('wiplimit', (m) => ({
  refused: m.canMove(CARDS, COLS, 'c1', 'doing'),
  allowed: m.canMove(CARDS, COLS, 'c1', 'done'),
  same_column: m.canMove(CARDS, COLS, 'c2', 'doing'),
  lifted: m.canMove(CARDS, m.setLimit(COLS, 'doing', null), 'c1', 'doing'),
  set: m.setLimit(COLS, 'todo', 5).map((c) => [c.id, c.wip]),
}));

feature('labels', (m) => ({
  all: m.all(CARDS), docs: ids(m.withTag(CARDS, 'DOCS')), counts: m.counts(CARDS),
}));

feature('search', (m) => ({
  urgent: ids(m.search(CARDS, 'URGENT')), empty: ids(m.search(CARDS, '')), blank: ids(m.search(CARDS, '   ')), miss: ids(m.search(CARDS, 'zzz')),
}));

feature('due', (m) => ({
  none: m.classify(CARDS[2], '2026-03-05'), overdue: m.classify(CARDS[3], '2026-03-05'),
  soon: m.classify(CARDS[0], '2026-03-08'), later: m.classify(CARDS[0], '2026-03-01'),
  today: m.classify(CARDS[1], '2026-03-04'), list: ids(m.overdue(CARDS, '2026-03-05')),
}));

feature('sortcolumn', (m) => ({
  by_due: ids(m.inColumnOrder(m.sortBy(CARDS, 'todo', 'due', 'asc'), 'todo')),
  by_title_desc: ids(m.inColumnOrder(m.sortBy(CARDS, 'doing', 'title', 'desc'), 'doing')),
  by_created: ids(m.inColumnOrder(m.sortBy(CARDS, 'todo', 'created', 'asc'), 'todo')),
  others_untouched: ids(m.inColumnOrder(m.sortBy(CARDS, 'todo', 'due', 'asc'), 'doing')),
}));

feature('archive', (m) => ({
  active: ids(m.active(CARDS)), archived: ids(m.archived(CARDS)),
  after_archive: ids(m.archived(m.archive(CARDS, 'c3'))), after_restore: ids(m.active(m.restore(CARDS, 'c6'))),
}));

feature('history', (m) => {
  let stack = m.empty();
  const s0 = { n: 0 }, s1 = { n: 1 }, s2 = { n: 2 };
  stack = m.push(stack, s0);
  stack = m.push(stack, s1);
  const u1 = m.undo(stack, s2);
  const u2 = m.undo(u1.stack, u1.state);
  const r1 = m.redo(u2.stack, u2.state);
  let big = m.empty();
  for (let i = 0; i < 30; i++) big = m.push(big, { n: i });
  const branch = m.push(u1.stack, { n: 9 });
  return {
    can_undo_empty: m.canUndo(m.empty()), can_undo: m.canUndo(stack), can_redo_before: m.canRedo(stack),
    u1: u1.state, can_redo_after: m.canRedo(u1.stack), u2: u2.state, r1: r1.state,
    undo_on_empty: m.undo(m.empty(), s2).state, cap: m.depth(big), branch_redo: m.canRedo(branch),
  };
});

feature('swimlanes', (m) => ({
  lanes: m.byAssignee(CARDS).map((l) => [l.assignee, ids(l.cards)]),
}));

feature('assignees', (m) => ({
  assigned: m.assign(CARDS, 'c3', 'cara').find((c) => c.id === 'c3').assignee,
  unassigned: m.unassign(CARDS, 'c1').find((c) => c.id === 'c1').assignee,
  workload: m.workload(CARDS), people: m.people(CARDS),
}));

feature('exporter', (m) => ({ json: m.toJSON(STATE), md: m.toMarkdown(STATE) }));

feature('importer', (m) => ({
  good: (() => { const r = m.parse(JSON.stringify({ version: 2, columns: COLS, cards: CARDS.slice(0, 2) })); return { cols: r.columns.length, cards: ids(r.cards), errors: r.errors }; })(),
  bad_json: m.parse('{not json').errors,
  no_columns: m.parse(JSON.stringify({ version: 2, cards: [] })).errors,
  bad_cards: (() => { const r = m.parse(JSON.stringify({ version: 2, columns: COLS, cards: [
    { id: 'x1', title: 'fine', column: 'todo', tags: [], created: '2026-03-01' },
    { id: 'x2', title: 'ghost column', column: 'nowhere', tags: [], created: '2026-03-01' },
    { id: 'x3', title: '', column: 'todo', tags: [], created: '2026-03-01' } ] })); return { kept: ids(r.cards), errors: r.errors }; })(),
}));

feature('metrics', (m) => ({
  cycle_done: m.cycleTime(CARDS[4]), cycle_open: m.cycleTime(CARDS[0]), avg: m.averageCycle(CARDS),
  week1: m.throughput(CARDS, '2026-02-23'), week0: m.throughput(CARDS, '2026-02-16'), week_jan: m.throughput(CARDS, '2026-01-12'),
}));

feature('persist', (m) => {
  const before = m.load();
  m.save(STATE);
  const after = m.load();
  const v1 = JSON.stringify({ version: 1, cards: [
    { id: 'a', title: 'A', status: 'Backlog', created: '2026-01-01' },
    { id: 'b', title: 'B', status: 'Doing', created: '2026-01-02' },
    { id: 'c', title: 'C', status: 'Backlog', created: '2026-01-03' } ] });
  const migrated = m.migrate(JSON.parse(v1));
  return {
    before, after_cols: after.columns.length, after_cards: ids(after.cards), key: m.KEY, stored: storage.length,
    stored_version: (() => { try { return JSON.parse(storage.getItem(m.KEY)).version; } catch (e) { return null; } })(),
    migrated_cols: migrated.columns.map((c) => c.name), migrated_cards: migrated.cards.map((c) => [c.id, c.column]),
    migrated_version: migrated.version,
  };
});

console.log(JSON.stringify(out));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def run_app(script):
    with tempfile.TemporaryDirectory() as tmp:
        d = Path(tmp)
        (d / "app.js").write_text(script, encoding="utf-8")
        (d / "driver.js").write_text(DRIVER, encoding="utf-8")
        done = subprocess.run([node(), str(d / "driver.js")], capture_output=True, text=True,
                              timeout=60, cwd=d)
        if done.returncode != 0:
            raise AssertionError("app script failed in node: %s" % done.stderr[-800:])
        return json.loads(done.stdout.strip().splitlines()[-1])


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % SCRIPT_ID, cls.raw, re.S | re.I)
        cls.script = m.group(1) if m else None
        cls.data, cls.error = None, None
        if cls.script and node():
            try:
                cls.data = run_app(cls.script)
            except (AssertionError, ValueError) as exc:
                cls.error = str(exc)

    def feature(self, name):
        self.assertIsNotNone(self.script, 'no <script id="%s"> block in the page' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no <section id=\"panel-%s\"> in the page" % name)
        got = self.data["features"].get(name)
        self.assertTrue(got and got.get("present"), "App.features.%s is missing" % name)
        self.assertTrue(got.get("has_model"), "App.features.%s.model must be an object of pure functions" % name)
        self.assertTrue(got.get("has_render"), "App.features.%s.render must be a function" % name)
        self.assertIsNone(got.get("error"), "App.features.%s.model threw: %s" % (name, got.get("error")))
        self.assertFalse(got.get("mutated_input"), "App.features.%s.model mutated its input" % name)
        return got

    # --- the page ---------------------------------------------------------
    def test_page_is_one_self_contained_html_file(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I), "page must be self-contained: found %s" % why)
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        tag = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>' % SCRIPT_ID, self.raw, re.I).group(0)
        self.assertNotIn("module", tag.lower(), "the app script must be a plain script, not type=module")
        self.assertRegex(self.raw, r"<nav\b", "the page needs a <nav> with the feature tabs")
        for name in FEATURES:
            self.assertRegex(self.raw, r'data-tab=["\']%s["\']' % name, "no tab for %s" % name)
            self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no panel for %s" % name)

    def test_app_script_defines_every_feature(self):
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        missing = [n for n in FEATURES if not (self.data["features"].get(n) or {}).get("present")]
        self.assertEqual(missing, [], "features missing from App.features: %s" % missing)

    # --- the sixteen features, one test each -------------------------------
    def test_feature_columns(self):
        got = self.feature("columns")
        self.assertEqual(got["original"], 3, "add() must not change the list it was given")
        self.assertEqual(got["after_add"], 4)
        self.assertEqual(got["new_col"]["name"], "Review")
        self.assertTrue(got["new_col"]["has_id"], "a new column needs an id")
        self.assertIsNone(got["new_col"]["wip"], "a new column has no WIP limit")
        self.assertEqual(got["renamed"], ["To do", "In progress", "Done"])
        self.assertEqual(got["removed"], ["todo", "done"])
        self.assertEqual(got["ok_errors"], [])
        self.assertTrue(got["blank_errors"], "a blank name must be refused")
        self.assertTrue(got["dup_errors"], "a duplicate name (case-insensitive) must be refused")

    def test_feature_cards(self):
        got = self.feature("cards")
        self.assertEqual(got["original"], 6, "add() must not change the list it was given")
        self.assertEqual(got["after_add"], 7)
        self.assertEqual(got["added"]["title"], "New card")
        self.assertEqual(got["added"]["column"], "todo")
        self.assertTrue(got["added"]["has_id"], "a new card needs a unique id")
        self.assertIs(got["added"]["archived"], False)
        self.assertIsNone(got["added"]["done"])
        self.assertEqual(got["updated"]["title"], "Design new logo")
        self.assertEqual(got["updated"]["due"], "2026-04-01")
        self.assertEqual(got["updated"]["column"], "todo", "update() keeps the fields the patch does not name")
        self.assertEqual(got["removed"], ["c1", "c3", "c4", "c5", "c6"])
        self.assertEqual(got["ok_errors"], [])
        self.assertGreaterEqual(len(got["bad_errors"]), 3, "blank title, empty tag and a non-ISO date are three errors")

    def test_feature_move(self):
        got = self.feature("move")
        self.assertEqual(got["todo_before"], ["c1", "c3"])
        self.assertEqual(got["done_before"], ["c5"], "inColumn() leaves archived cards out")
        self.assertEqual(got["to_done_first"], ["c1", "c5"], "index 0 puts the card first")
        self.assertEqual(got["to_doing_last"], ["c2", "c4", "c3"], "an index past the end puts the card last")
        self.assertEqual(got["reorder"], ["c4", "c2"], "a move inside a column reorders it")
        self.assertEqual(got["original_todo"], ["c1", "c3"], "move() must not touch the list it was given")
        self.assertEqual(got["untouched_after_move"], 6, "a move keeps every card")

    def test_feature_wiplimit(self):
        got = self.feature("wiplimit")
        self.assertFalse(got["refused"]["ok"], "Doing holds 2 with a limit of 2: a third card is refused")
        self.assertTrue(got["refused"]["reason"], "a refusal names its reason")
        self.assertTrue(got["allowed"]["ok"])
        self.assertTrue(got["same_column"]["ok"], "reordering inside a full column is not a new card")
        self.assertTrue(got["lifted"]["ok"], "a null limit means unlimited")
        self.assertEqual(got["set"], [["todo", 5], ["doing", 2], ["done", None]])

    def test_feature_labels(self):
        got = self.feature("labels")
        self.assertEqual(got["all"], ["bug", "design", "docs", "infra", "release", "Urgent"], "unique, sorted case-insensitively, case kept")
        self.assertEqual(got["docs"], ["c1", "c4"], "tag match is case-insensitive")
        self.assertEqual(got["counts"], {"bug": 2, "design": 1, "docs": 2, "infra": 1, "release": 1, "Urgent": 1})

    def test_feature_search(self):
        got = self.feature("search")
        self.assertEqual(got["urgent"], ["c5"], "search covers the description, case-insensitively")
        self.assertEqual(got["empty"], ["c1", "c2", "c3", "c4", "c5", "c6"])
        self.assertEqual(got["blank"], got["empty"], "whitespace is no query")
        self.assertEqual(got["miss"], [])

    def test_feature_due(self):
        got = self.feature("due")
        self.assertEqual(got["none"], "none")
        self.assertEqual(got["overdue"], "overdue")
        self.assertEqual(got["soon"], "soon", "within three days is soon")
        self.assertEqual(got["later"], "later")
        self.assertEqual(got["today"], "soon", "due today is soon, not overdue")
        self.assertEqual(got["list"], ["c2", "c4"], "overdue() keeps board order and skips done cards")

    def test_feature_sortcolumn(self):
        got = self.feature("sortcolumn")
        self.assertEqual(got["by_due"], ["c1", "c3"], "a missing due date sorts last")
        self.assertEqual(got["by_title_desc"], ["c4", "c2"])
        self.assertEqual(got["by_created"], ["c3", "c1"])
        self.assertEqual(got["others_untouched"], ["c2", "c4"], "sorting one column leaves the others as they were")

    def test_feature_archive(self):
        got = self.feature("archive")
        self.assertEqual(got["active"], ["c1", "c2", "c3", "c4", "c5"])
        self.assertEqual(got["archived"], ["c6"])
        self.assertEqual(got["after_archive"], ["c3", "c6"])
        self.assertEqual(got["after_restore"], ["c1", "c2", "c3", "c4", "c5", "c6"])

    def test_feature_history(self):
        got = self.feature("history")
        self.assertIs(got["can_undo_empty"], False)
        self.assertIs(got["can_undo"], True)
        self.assertIs(got["can_redo_before"], False)
        self.assertEqual(got["u1"], {"n": 1}, "undo returns the state pushed last")
        self.assertIs(got["can_redo_after"], True)
        self.assertEqual(got["u2"], {"n": 0})
        self.assertEqual(got["r1"], {"n": 1}, "redo walks forward again")
        self.assertEqual(got["undo_on_empty"], {"n": 2}, "undo with nothing to undo returns the state unchanged")
        self.assertEqual(got["cap"], 20, "the undo stack keeps at most 20 states")
        self.assertIs(got["branch_redo"], False, "a new push after undo clears the redo branch")

    def test_feature_swimlanes(self):
        got = self.feature("swimlanes")
        self.assertEqual(got["lanes"], [["ana", ["c1", "c4"]], ["ben", ["c2", "c5"]], ["Unassigned", ["c3"]]],
                         "lanes sorted by name, Unassigned last, archived cards out")

    def test_feature_assignees(self):
        got = self.feature("assignees")
        self.assertEqual(got["assigned"], "cara")
        self.assertIsNone(got["unassigned"])
        self.assertEqual(got["workload"], {"ana": 2, "ben": 2}, "workload counts active cards only")
        self.assertEqual(got["people"], ["ana", "ben"], "people() lists assignees of active cards, sorted")

    def test_feature_exporter(self):
        got = self.feature("exporter")
        data = json.loads(got["json"])
        self.assertEqual(data.get("version"), 2)
        self.assertEqual([c["id"] for c in data["columns"]], ["todo", "doing", "done"])
        self.assertEqual(len(data["cards"]), 6)
        md = got["md"]
        self.assertIn("## To do", md)
        self.assertIn("## Doing", md)
        self.assertIn("- [ ] Write spec", md)
        self.assertIn("- [x] Set up CI", md, "a done card is a checked item")
        self.assertNotIn("Old task", md, "archived cards stay out of the export")
        self.assertLess(md.index("## To do"), md.index("## Doing"), "columns keep their order")

    def test_feature_importer(self):
        got = self.feature("importer")
        self.assertEqual(got["good"]["cols"], 3)
        self.assertEqual(got["good"]["cards"], ["c1", "c2"])
        self.assertEqual(got["good"]["errors"], [])
        self.assertTrue(got["bad_json"], "invalid JSON is an error, not an exception")
        self.assertTrue(got["no_columns"], "a document without columns is an error")
        self.assertEqual(got["bad_cards"]["kept"], ["x1"], "only the valid cards are kept")
        self.assertEqual(len(got["bad_cards"]["errors"]), 2, "one error per rejected card")

    def test_feature_metrics(self):
        got = self.feature("metrics")
        self.assertEqual(got["cycle_done"], 6, "created 02-21, done 02-27: six days")
        self.assertIsNone(got["cycle_open"])
        self.assertAlmostEqual(got["avg"], 4.0, places=6, msg="mean of 6 (c5) and 2 (c6)")
        self.assertEqual(got["week1"], 1, "one card done in the week of 02-23")
        self.assertEqual(got["week0"], 0)
        self.assertEqual(got["week_jan"], 1, "archived cards still count as done work")

    def test_feature_persist(self):
        got = self.feature("persist")
        self.assertIsNone(got["before"], "load() with nothing saved returns null")
        self.assertEqual(got["after_cols"], 3)
        self.assertEqual(got["after_cards"], ["c1", "c2", "c3", "c4", "c5", "c6"])
        self.assertTrue(got["key"], "persist.model.KEY names the storage key")
        self.assertEqual(got["stored_version"], 2, "saved documents carry version 2")
        self.assertEqual(got["migrated_version"], 2)
        self.assertEqual(got["migrated_cols"], ["Backlog", "Doing"], "v1 statuses become columns in order of first appearance")
        self.assertEqual([c[0] for c in got["migrated_cards"]], ["a", "b", "c"])
        self.assertEqual(got["migrated_cards"][0][1], got["migrated_cards"][2][1], "a and c share the Backlog column")
        self.assertNotEqual(got["migrated_cards"][0][1], got["migrated_cards"][1][1])


