ui_scenario:
// Kanban Board, what a person does on the page. Runs in the page after the seed; every
// step names an action and what must then be true. State is read through App.store, the
// contract every build honours; controls are found the way a person finds them, by label.
const sleep = ms => new Promise(r => setTimeout(r, ms));
const steps = window.__ui_steps = [];   // shared with the gate, so a timeout keeps what ran
const step = (name, ok, note) => steps.push({ name, ok: !!ok, note: note || '' });
const S = () => App.store.get();
const tab = async n => { const b = document.querySelector('nav button[data-tab="' + n + '"]'); if (b) b.click(); await sleep(60); return document.getElementById('panel-' + n); };
const setv = (el, v) => { if (!el) return false; el.focus(); el.value = v; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); return true; };
const label = el => ((el.placeholder || '') + ' ' + (el.name || '') + ' ' + (el.id || '') + ' ' + (el.getAttribute('aria-label') || '') + ' ' + (el.closest('label') ? el.closest('label').textContent : '')).toLowerCase();
const submit = (el, rx) => { if (!el) return false; const form = el.closest('form'); const scope = form || el.closest('.panel') || document; const btn = [...scope.querySelectorAll('button')].find(b => rx.test(b.textContent)); if (form && form.requestSubmit) { try { form.requestSubmit(btn || undefined); return true; } catch (e) {} } if (btn) { btn.click(); return true; } return false; };
const text = el => el ? (el.textContent || '') : '';   // textContent: a hidden panel has no innerText

// 1. Columns tab: type a name, add it
let p = await tab('columns'); let n0 = S().columns.length;
const colIn = [...p.querySelectorAll('input')].find(i => i.type !== 'number' && i.type !== 'hidden' && !i.dataset.rename && /name|column|new/.test(label(i))) || [...p.querySelectorAll('input')].find(i => i.type !== 'number' && i.type !== 'hidden');
setv(colIn, 'Scenario column'); submit(colIn, /add|create|new/i); await sleep(120);
step('add a column from the Columns tab', S().columns.length === n0 + 1 && S().columns.some(c => /scenario column/i.test(c.name)), '');

// 2. Cards tab: fill the form, add a card
p = await tab('cards'); n0 = S().cards.length;
const ins = [...p.querySelectorAll('input, select, textarea')];
const titleIn = ins.find(i => /title/.test(label(i))) || ins.find(i => i.tagName === 'INPUT' && i.type === 'text');
setv(titleIn, 'Scenario card'); const d = ins.find(i => /desc/.test(label(i))); if (d) setv(d, 'from the scenario');
const due = ins.find(i => /due/.test(label(i))); if (due) setv(due, '2026-03-20');
submit(titleIn, /add|save|create/i); await sleep(150);
const card = S().cards.find(c => c.title === 'Scenario card');
step('add a card from the Cards tab', !!card && !card.archived, card ? 'column ' + card.column : '');

// 3. a blank title is refused and a message is shown
p = await tab('cards'); n0 = S().cards.length;
const ins2 = [...p.querySelectorAll('input, select, textarea')];
const t2 = ins2.find(i => /title/.test(label(i))) || ins2.find(i => i.tagName === 'INPUT' && i.type === 'text');
setv(t2, '   '); submit(t2, /add|save|create/i); await sleep(120);
step('a blank card title is refused with a message', S().cards.length === n0 && /blank|empty|required|title|invalid/i.test(text(document.getElementById('panel-cards'))), '');

// 4. Move tab: the card is on the board and some control moves it to another column
p = await tab('move');
const before = card && S().cards.find(c => c.id === card.id).column;
const other = S().columns.find(c => c.id !== before);
step('the Move tab shows the card on the board', /scenario card/i.test(text(p)), '');
let moved = false;
if (other) {
  // shape 1: selects for the card and the column (any order) plus a move button
  const sels = [...p.querySelectorAll('select')];
  for (const sel of sels) {
    const cardOpt = [...sel.options].find(o => o.value === card.id || /scenario card/i.test(o.text));
    const colOpt = [...sel.options].find(o => o.value === other.id || new RegExp('^' + other.name + '$', 'i').test(o.text.trim()));
    if (cardOpt) setv(sel, cardOpt.value); else if (colOpt) setv(sel, colOpt.value);
  }
  const idIn = [...p.querySelectorAll('input')].find(i => /card|id/.test(label(i)) && i.type === 'text'); if (idIn) setv(idIn, card.id);
  const colIn = [...p.querySelectorAll('input')].find(i => /column|to/.test(label(i)) && i.type === 'text'); if (colIn) setv(colIn, other.id);
  const go = [...p.querySelectorAll('button')].find(b => /^(move( card)?|go|apply)$/i.test(b.textContent.trim())); if (go) { go.click(); await sleep(150); }
  moved = S().cards.find(c => c.id === card.id).column !== before;
  // shape 2: a per-card button naming the target column
  if (!moved) { const b = [...p.querySelectorAll('button')].find(b => new RegExp(other.name, 'i').test(b.textContent) && b.closest('.card, li, tr, [data-card], [data-id]') && /scenario card/i.test(text(b.closest('.card, li, tr, [data-card], [data-id]')))); if (b) { b.click(); await sleep(150); } moved = S().cards.find(c => c.id === card.id).column !== before; }
  // shape 3: select the card somewhere, then a "Move to <column>" button
  if (!moved) { const b = [...p.querySelectorAll('button')].find(b => new RegExp('move to ' + other.name, 'i').test(b.textContent)); if (b) { b.click(); await sleep(150); } moved = S().cards.find(c => c.id === card.id).column !== before; }
}
step('a control on the Move tab moves the card to another column', moved, other ? 'to ' + other.name : 'no other column');

// 5. WIP tab: set a limit of 1 on a column, then a move into it is refused with a reason
p = await tab('wiplimit');
const target = S().columns.find(c => c.id !== S().cards.find(x => x.id === card.id).column) || S().columns[0];
const wipIn = [...p.querySelectorAll('input')].find(i => (i.dataset.wip === target.id) || (i.dataset.col === target.id) || (i.type === 'number' && (i.closest('tr, li, div') && new RegExp(target.name, 'i').test(text(i.closest('tr, li, div')))))) || [...p.querySelectorAll('input')].find(i => i.type === 'number');
setv(wipIn, '1'); submit(wipIn, /set|apply|save|update/i); await sleep(150);
const limited = S().columns.find(c => c.wip === 1);
step('set a WIP limit of 1 from the WIP tab', !!limited, limited ? limited.name : '');
const full = limited && S().cards.filter(c => c.column === limited.id && !c.archived).length >= 1;
const verdict = limited && App.features.wiplimit.model.canMove(full ? S().cards : S().cards.concat([{ id: 'zz', title: 'x', column: limited.id, archived: false, tags: [] }]), S().columns, card.id, limited.id);
step('a move into a full column is refused with a reason', verdict && verdict.ok === false && !!verdict.reason, verdict ? verdict.reason : '');

// 6. History tab: Undo reverts the last change
const snapshot = JSON.stringify([S().columns, S().cards]);
p = await tab('history');
const undo = [...p.querySelectorAll('button')].find(b => /undo/i.test(b.textContent));
if (undo) { undo.click(); await sleep(150); }
step('Undo on the History tab reverts the last change', !!undo && JSON.stringify([S().columns, S().cards]) !== snapshot, undo ? '' : 'no Undo button');
const redo = [...document.getElementById('panel-history').querySelectorAll('button')].find(b => /redo/i.test(b.textContent));
if (redo) { redo.click(); await sleep(150); }
step('Redo brings the change back', !!redo && JSON.stringify([S().columns, S().cards]) === snapshot, '');

// 7. Export tab shows the JSON and the Markdown with the card
p = await tab('exporter');
for (const b of [...p.querySelectorAll('button')].filter(b => /json|markdown|show|export/i.test(b.textContent)).slice(0, 3)) { b.click(); await sleep(80); }
const dump = text(document.getElementById('panel-exporter')) + [...document.getElementById('panel-exporter').querySelectorAll('textarea')].map(t => t.value).join(' ');
step('Export tab shows JSON and Markdown holding the board', /"columns"|columns/.test(dump) && /##|- \[/.test(dump), '');

// 8. Import tab: a document with one valid and one invalid card adds one and reports one
p = await tab('importer'); n0 = S().cards.length;
const ta = p.querySelector('textarea, input[type=text]');
setv(ta, JSON.stringify({ version: 2, columns: [{ id: 'imp', name: 'Imported', wip: null }], cards: [{ id: 'imp1', title: 'Imported card', column: 'imp', tags: [], created: '2026-03-01' }, { id: 'imp2', title: '', column: 'imp', tags: [], created: '2026-03-01' }] }));
submit(ta, /import|load|add|parse/i); await sleep(200);
step('Import adds the valid card', S().cards.some(c => c.title === 'Imported card'), '');
step('Import reports the invalid card on the page', /blank|invalid|title|error|rejected|skipped/i.test(text(document.getElementById('panel-importer'))), '');

// 9. Search narrows, Archive removes from the board
p = await tab('search'); const q = p.querySelector('input, textarea'); setv(q, 'scenario'); await sleep(150);
step('Search narrows to the scenario card', /scenario card/i.test(text(document.getElementById('panel-search'))) && !/imported card/i.test(text(document.getElementById('panel-search'))), '');
p = await tab('archive');
const arc = [...p.querySelectorAll('button')].find(b => /archive/i.test(b.textContent) && !/restore|un/i.test(b.textContent) && b.closest('li, tr, div') && /scenario card|imported card|write spec/i.test(text(b.closest('li, tr, div'))));
if (arc) { arc.click(); await sleep(150); }
step('Archive on a card takes it off the board', !!arc && S().cards.some(c => c.archived && /scenario card|imported card|write spec/i.test(c.title)), arc ? '' : 'no Archive button');

